public class TestMain {
    public static void main(String[] args) {
        String[][] cases = {
        {"a:3u b:5u", "write a=0 b=0", "00"},
        {"a:3u b:5u", "read 00", "a=0 b=0"},
        {"count:6u batt:8u", "write count=0 batt=7", "001c"},
        {"count:6u batt:8u", "read 001c", "count=0 batt=7"},
        {"count:6u batt:8u", "write count=64 batt=7", "error: value count"},
        };
        int failed = 0;
        for (int i = 0; i < cases.length; i++) {
            String[] c = cases[i];
            String want = c[2];
            String got;
            try {
                got = Bitwire.wire(c[0], c[1]);
            } catch (Throwable e) {
                got = "EXCEPTION " + e;
            }
            if (!want.equals(got)) {
                failed++;
                System.out.println("case " + i + " FAILED\n  args: " + String.join(" | ", java.util.Arrays.copyOf(c, 2)) + "\n  got:  " + got + "\n  want: " + want);
            }
        }
        System.out.println((cases.length - failed) + "/" + cases.length + " cases passed");
        if (failed > 0) System.exit(1);
    }
}

