public class TestMain {
    public static void main(String[] args) {
        String[][] cases = {
        {"a:3u b:5u", "write a=0 b=3", "03"},
        {"a:3u b:5u", "read 03", "a=0 b=3"},
        {"wind:1e(calm|gusty) batt:4u rpm:4u trim:12i ph:4i.2 #sum", "write wind=calm batt=2 rpm=1 trim=1 ph=-0.03", "10800e801e"},
        {"wind:1e(calm|gusty) batt:4u rpm:4u trim:12i ph:4i.2 #sum", "read 10800e801e", "wind=calm batt=2 rpm=1 trim=1 ph=-0.03"},
        {"wind:1e(calm|gusty) batt:4u rpm:4u trim:12i ph:4i.2 #sum", "write wind=nope batt=2 rpm=1 trim=1 ph=-0.03", "error: value wind"},
        };
        int failed = 0;
        for (int i = 0; i < cases.length; i++) {
            String[] c = cases[i];
            String want = c[2];
            String got;
            try {
                got = Bitwire.wire(c[0], c[1]);
            } catch (Throwable e) {
                got = "EXCEPTION " + e;
            }
            if (!want.equals(got)) {
                failed++;
                System.out.println("case " + i + " FAILED\n  args: " + String.join(" | ", java.util.Arrays.copyOf(c, 2)) + "\n  got:  " + got + "\n  want: " + want);
            }
        }
        System.out.println((cases.length - failed) + "/" + cases.length + " cases passed");
        if (failed > 0) System.exit(1);
    }
}

