#include <stdlib.h>
#include "bitwire.h"

/* layout-driven bit packer */
char *wire(const char *layout, const char *request) {
    (void)layout;
    (void)request;
    char *r = malloc(1);
    if (r) r[0] = '\0';
    return r; /* write me: see README.md */
}

