#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "bitwire.h"

static int failed = 0;

static void check(int i, char *got, const char *want) {
    if (!got || strcmp(got, want) != 0) {
        failed++;
        printf("case %d FAILED\n  got:  [%s]\n  want: [%s]\n", i, got ? got : "(null)", want);
    }
    free(got);
}

int main(void) {
    check(0, wire("a:3u b:5u", "enc a=3 b=23"), "77");
    check(1, wire("a:3u b:5u", "dec 77"), "a=3 b=23");
    check(2, wire("_:4 bins:4i*2 temp:5i volt:5i.1 mode:2e(off|eco|auto|boost) slot:8u #xor", "enc bins=4,0 temp=-1 volt=-0.4 mode=off slot=1"), "040FF001FA");
    check(3, wire("_:4 bins:4i*2 temp:5i volt:5i.1 mode:2e(off|eco|auto|boost) slot:8u #xor", "dec 040FF001FA"), "bins=4,0 temp=-1 volt=-0.4 mode=off slot=1");
    check(4, wire("_:4 bins:4i*2 temp:5i volt:5i.1 mode:2e(off|eco|auto|boost) slot:8u #xor", "enc bins=8 temp=-1 volt=-0.4 mode=off slot=1"), "error: value bins");
    if (failed) {
        printf("%d case(s) failed\n", failed);
        return 1;
    }
    printf("all cases passed\n");
    return 0;
}
